const crypto = require('crypto');
const input = $input.first().json || {};
const body = input.body && typeof input.body === 'object' ? input.body : input;
const headers = Object.fromEntries(Object.entries(input.headers || {}).map(([k, v]) => [String(k).toLowerCase(), String(v)]));
const secret = String($env.SNAPGAD_N8N_SHARED_SECRET || '');
const timestamp = headers['x-snapgad-timestamp'];
const signature = headers['x-snapgad-signature'];
const fail = (message, code) => [{ json: { valid: false, httpStatus: code, error: { code: 'INVALID_COPY_REQUEST', message } } }];
const stable = (value) => {
  if (Array.isArray(value)) return '[' + value.map(stable).join(',') + ']';
  if (value && typeof value === 'object') return '{' + Object.keys(value).sort().map((key) => JSON.stringify(key) + ':' + stable(value[key])).join(',') + '}';
  return JSON.stringify(value);
};
if (!secret || !timestamp || !signature) return fail('Faltan encabezados de firma.', 401);
const age = Math.abs(Date.now() - Number(timestamp) * 1000);
if (!Number.isFinite(age) || age > 300000) return fail('La firma esta vencida.', 401);
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(String(timestamp) + '.' + stable(body)).digest('hex');
const a = Buffer.from(signature); const b = Buffer.from(expected);
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return fail('Firma invalida.', 401);
const required = ['contentItemId', 'ownerId', 'assetUrl', 'idempotencyKey', 'brief'];
if (required.some((key) => !body[key])) return fail('Faltan campos obligatorios.', 400);
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(String(body.idempotencyKey))) return fail('idempotencyKey debe ser UUID.', 400);
if (!/^https:\/\/[^\s]+$/i.test(String(body.assetUrl))) return fail('assetUrl debe ser HTTPS.', 400);
if (typeof body.brief !== 'object' || !body.brief.service || !body.brief.niche || !body.brief.objective || !body.brief.cta || !body.brief.humanDescription || !Array.isArray(body.brief.allowedFacts) || body.brief.allowedFacts.length < 1) return fail('brief incompleto.', 400);
return [{ json: { valid: true, httpStatus: 202, jobType: 'COPY_REQUEST', receivedAt: new Date().toISOString(), contentItemId: String(body.contentItemId), ownerId: String(body.ownerId), assetUrl: String(body.assetUrl), idempotencyKey: String(body.idempotencyKey), brief: body.brief } }];

const original = $('Copy — Verificar Firma y Schema').first().json;
